UPDATE utb_app_mst
SET
    retain_seq = #{req.clientRef}
  , app_route = #{req.appRouteCode}
  , app_state = #{req.statusCode}
  , state = #{req.stateCode}
  , country_code = #{req.countryCode}
  , right_category = #{req.rightTypeCode}
  , product_class = #{req.goodsClass}
  , app_name_ko = #{req.titleKo}
  , app_name_en = #{req.titleEn}
  , etc_title = #{req.etcTitle}
  , outsourcing_corp_name = #{req.annuityAgency}
  , outsourcing_yn = #{req.outsourcingYn}
  , give_up_content = #{req.abandonNote}
  , app_category = #{req.appCategoryCode}
  , app_name = #{req.appName}
  , grade = #{req.gradeCode}
  , independent_claim = #{req.independentClaims}
  , dependent_claim = #{req.dependentClaims}
  , drawing_paper_count = #{req.drawingCount}
  , ulti_dependent_claim_count = #{req.finalClaimsCount}
  , app_no = #{req.appNo}
  , first_app_no = #{req.firstAppNo}
  , original_app_no = #{req.originalAppNo}
  , original_reg_no = #{req.originalRegNo}
  , double_app_no = #{req.dualAppNo}
  , global_app_no = #{req.globalAppNo}
  , global_reg_no = #{req.globalRegNo}
  , reg_no = #{req.regNo}
  , open_no = #{req.pubNo}
  , product_class_app_no = #{req.productClassAppNo}
  , re_app_no = #{req.reAppNo}
  , public_no = #{req.announcementNo}
  , reg_public_no = #{req.regAnnounceNo}
  , madrid_no = #{req.madridAppNo}
  , ipc_category_code = #{req.ipcClassification}
  , external_app_approach = #{req.externalAppApproach}
  , year_cnt_management_yn = #{req.isAnnuityManaged}
  , external_app_yn = #{req.isForeignApp}
  , trademark_research_yn = #{req.isTrademarkResearch}
  , renewal_management_yn = #{req.isRenewalManaged}
  , interior_preference_assert_yn = #{req.hasDomesticPriority}
  , mandate_paper_submit_yn = #{req.isPoaSubmitted}
  , note = #{req.note}
  , app_classification = #{req.categoryCode}
  , app_kind = #{req.appTypeCode}
  , app_language = #{req.appLanguageCode}
  , proposal_name = #{req.proposal}
  , foreign_app_timing = #{req.foreignAppTimingCode}
  , access_code = #{req.accessCode}
  , annuity_year = #{req.annuityYear}
  , annuity_reduc_rate = #{req.annuityReducRateCode}
  , spec_page = #{req.specPage}
  , figure_count = #{req.figureCount}
  , reg_reduction_rate = #{req.regReductionRateCode}
  , asset_no = #{req.ourRef}
  , agent_ref = #{req.yourRef}
  , dept_code = #{req.deptName}
  , trademark_renewal_fee = #{req.trademarkRenewalFee}
  , renewal_late_fee = #{req.renewalLateFee}
  , next_payment_installment = #{req.nextPaymentInstallment}
  , parent_reg_app_no = #{req.parentRegAppNo}
  , domestic_reg_no = #{req.domesticRegNo}
  , goods_app_no = #{req.productClassAppNo}
  , client_name = #{req.clientNm}
  , applicant_name = #{req.applicantNm}
  , reg_mgr_name = #{req.regMgrNm}
  , kipo_delay_days = #{req.kipoDelayDays}
  , update_user = #{updateUser}
  , update_at = CURRENT_TIMESTAMP
WHERE app_seq = #{appSeq}
  AND office_seq = #{officeSeq}
  AND del_yn = 'N'

UPDATE utb_app_patent
SET summary = #{summary}
  , claim_scope = #{claimScope}
  , update_user = #{updateUser}
  , update_at = CURRENT_TIMESTAMP
WHERE office_seq = #{officeSeq}
  AND app_seq = #{appSeq}
  AND patent_seq = #{patentSeq}
  AND del_yn = 'N'

UPDATE utb_app_design
SET design_summary = #{designSummary}
  , design_description = #{designDescription}
  , multi_design = #{multiDesign}
  , is_partial_design = #{isPartialDesign}
  , update_user = #{updateUser}
  , update_at = CURRENT_TIMESTAMP
WHERE office_seq = #{officeSeq}
  AND app_seq = #{appSeq}
  AND design_seq = #{designSeq}
  AND del_yn = 'N'

UPDATE utb_app_trademark
SET update_user = #{updateUser}
  , update_at = CURRENT_TIMESTAMP
WHERE office_seq = #{officeSeq}
  AND app_seq = #{appSeq}
  AND trademark_seq = #{trademarkSeq}
  AND del_yn = 'N'

mapper.select:
SELECT /* ========================= 기본 출원 정보 ========================= */ am.right_category AS rightTypeCode , fn_get_cd_nm('PAT_TYPE',am.right_category) AS rightTypeCodeName , am.app_classification AS appClassificationCode , fn_get_cd_nm('NAT_IO_DIV',am.app_classification) AS appClassificationCodeName , am.asset_no AS ourRef , am.agent_ref AS yourRef , am.country_code AS countryCode , fn_get_ctry_nm(am.country_code,'C','KO') AS countryCodeName , am.domestic_reg_no as domesticRegNo /* 출원국가명 (스칼라 서브쿼리) */ , (SELECT cc.ctry_ko_nm FROM utb_contry_code cc WHERE cc.ctry_code = am.country_code LIMIT 1) AS appCountry , am.app_no AS appNo , am.reg_no AS regNo , am.retain_seq AS clientRef
/* ========================= 날짜 정보 (1:N → 최신 1건) ========================= */
/* 출원일 */ , ( SELECT to_char(dd.duedate_date, 'YYYYMMDD') FROM utb_duedate_mapp dm JOIN utb_duedate_mst dd ON dd.duedate_seq = dm.duedate_seq WHERE dm.tbl_seq = am.app_seq AND dd.duedate_category_code = 'appDate' AND dd.del_yn = 'N' ORDER BY dd.create_at DESC LIMIT 1 ) AS appDate
/* 출원/공고일 (출원일 우선) */ , ( SELECT to_char(dd.duedate_date, 'YYYYMMDD') FROM utb_duedate_mapp dm JOIN utb_duedate_mst dd ON dd.duedate_seq = dm.duedate_seq WHERE dm.tbl_seq = am.app_seq AND dd.duedate_category_code = 'pubDate' AND dd.del_yn = 'N' ORDER BY dd.create_at DESC LIMIT 1 ) AS pubDate
/* 등록일 */ , ( SELECT to_char(dd.duedate_date, 'YYYYMMDD') FROM utb_duedate_mapp dm JOIN utb_duedate_mst dd ON dd.duedate_seq = dm.duedate_seq WHERE dm.tbl_seq = am.app_seq AND dd.duedate_category_code = 'regDate' AND dd.del_yn = 'N' ORDER BY dd.create_at DESC LIMIT 1 ) AS regDate
/* ========================= 명칭 / 물품류 ========================= */
, am.app_name_ko AS titleKo , am.app_name_en AS titleEn , am.product_class AS goodsClass
/* ========================= 사람 정보 (participant) ========================= */
, /* 해외대리인 */ ( SELECT ui.user_info_seq as foreignAgent FROM utb_participant p JOIN utb_user_info ui ON ui.user_info_seq = p.user_info_seq AND ui.office_seq = p.office_seq AND ui.del_yn = 'N' WHERE p.tbl_seq = am.app_seq AND p.participant_code = 'foreignAgent' AND p.del_yn = 'N' ORDER BY CASE WHEN p.main_yn = 'Y' THEN 1 ELSE 2 END, p.create_at DESC LIMIT 1 ) AS foreignAgent , fn_get_participant_name(am.office_seq, am.app_seq, 'foreignAgent') AS foreignAgentName , /* 의뢰인 */ ( SELECT ui.user_info_seq FROM utb_participant p JOIN utb_user_info ui ON ui.user_info_seq = p.user_info_seq AND ui.office_seq = p.office_seq AND ui.del_yn = 'N' WHERE p.tbl_seq = am.app_seq AND p.participant_code = 'client' AND p.del_yn = 'N' ORDER BY CASE WHEN p.main_yn = 'Y' THEN 1 ELSE 2 END, p.create_at DESC LIMIT 1 ) AS client , fn_get_participant_name(am.office_seq, am.app_seq, 'client') AS clientName , /* 출원인 */ ( SELECT ui.user_info_seq FROM utb_participant p JOIN utb_user_info ui ON ui.user_info_seq = p.user_info_seq AND ui.office_seq = p.office_seq AND ui.del_yn = 'N' WHERE p.tbl_seq = am.app_seq AND p.participant_code = 'applicant' AND p.del_yn = 'N' ORDER BY CASE WHEN p.main_yn = 'Y' THEN 1 ELSE 2 END, p.create_at DESC LIMIT 1 ) AS applicant , fn_get_participant_name(am.office_seq, am.app_seq, 'applicant') AS applicantName FROM utb_app_mst am WHERE am.app_seq = #{appSeq} AND am.office_seq = #{officeSeq} AND am.del_yn = 'N'
